// Check for custom projects stored locally by admin
function loadStoredProjects() {
  try {
    // Automatically purge old stale caches that have fewer than the full master 19 projects
    const staleKeys = ['mustafa_portfolio_projects_v5', 'mustafa_portfolio_projects_v6', 'mustafa_portfolio_projects_v8'];
    staleKeys.forEach(k => {
      const item = localStorage.getItem(k);
      if (item) {
        try {
          const parsed = JSON.parse(item);
          if (!Array.isArray(parsed) || parsed.length < DEFAULT_PORTFOLIO_PROJECTS.length) {
            localStorage.removeItem(k);
          }
        } catch (e) {
          localStorage.removeItem(k);
        }
      }
    });

    const saved = localStorage.getItem('mustafa_portfolio_projects_v8');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length >= DEFAULT_PORTFOLIO_PROJECTS.length) {
        return parsed;
      }
    }
  } catch (e) {
    console.warn('Could not load stored projects from localStorage:', e);
  }
  return DEFAULT_PORTFOLIO_PROJECTS;
}

let PORTFOLIO_PROJECTS = loadStoredProjects();

// Helper functions for Admin Panel
function savePortfolioProjects(projects) {
  try {
    localStorage.setItem('mustafa_portfolio_projects_v8', JSON.stringify(projects));
    PORTFOLIO_PROJECTS = projects;

    // Directly persist to disk via backend API
    try {
      fetch('/api/save-portfolio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(projects)
      }).then(r => r.json()).then(data => {
        console.log('[Sync] Saved to disk permanently:', data);
      }).catch(err => {
        console.warn('[Sync] Offline or static host - saved to browser localStorage only.');
      });
    } catch (e) {}

    return true;
  } catch (e) {
    console.error('Failed to save to localStorage:', e);
    return false;
  }
}

function resetPortfolioProjects() {
  localStorage.removeItem('mustafa_portfolio_projects_v5');
  localStorage.removeItem('mustafa_portfolio_projects_v6');
  localStorage.removeItem('mustafa_portfolio_projects_v8');
  PORTFOLIO_PROJECTS = DEFAULT_PORTFOLIO_PROJECTS;
  return DEFAULT_PORTFOLIO_PROJECTS;
}

if (typeof window !== 'undefined') {
  window.DEFAULT_PORTFOLIO_PROJECTS = DEFAULT_PORTFOLIO_PROJECTS;
  window.PORTFOLIO_PROJECTS = PORTFOLIO_PROJECTS;
  window.savePortfolioProjects = savePortfolioProjects;
  window.resetPortfolioProjects = resetPortfolioProjects;
}

if (typeof module !== 'undefined') {
  module.exports = { DEFAULT_PORTFOLIO_PROJECTS, PORTFOLIO_PROJECTS, savePortfolioProjects, resetPortfolioProjects };
}
